-- AQARI V267 Preview/Staging: fix PL/pgSQL lease row ambiguity in extra official forms.
create or replace function private.aqari_official_source(w uuid,k text,t text,i uuid,source_id uuid,fields jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;lease_row public.aqari_leases;mon text;breakdown jsonb;discount numeric;why text;actor text;adj jsonb;begin if k not in('exit_notice','discount_approval') then return private.aqari_official_source_pre_exit_20260915(w,k,t,i,source_id,fields);end if;if t is distinct from 'lease' then raise exception 'DOCUMENT_KIND_ENTITY_MISMATCH' using errcode='22023';end if;if source_id is not null then raise exception 'DOCUMENT_SOURCE_NOT_EXPECTED' using errcode='22023';end if;if not private.aqari_official_entity_scope(w,'lease',i,'read') then raise insufficient_privilege using message='DOCUMENT_ENTITY_NOT_FOUND';end if;select x.* into lease_row from public.aqari_leases x where x.workspace_id=w and x.id=i and x.status in('signed','expired');if not found then raise exception 'DOCUMENT_ACTIVE_LEASE_REQUIRED' using errcode='23514';end if;select jsonb_build_object('tenantName',q.full_name,'propertyName',p.name,'unitNo',u.unit_no,'contractNo',lease_row.contract_no) into result from public.aqari_tenants q join public.aqari_units u on u.workspace_id=w and u.id=lease_row.unit_id join public.aqari_properties p on p.workspace_id=w and p.id=u.property_id where q.workspace_id=w and q.id=lease_row.tenant_id;if k='exit_notice' then select result||jsonb_build_object('vacateDate',s.vacate_date::text) into result from private.aqari_vacating_settlements s where s.workspace_id=w and s.lease_id=i;if result ? 'vacateDate' is false then raise exception 'DOCUMENT_VACATING_RECORD_REQUIRED' using errcode='23514';end if;return result;end if;select coalesce(nullif(p.display_name,''),auth.uid()::text) into actor from public.aqari_profiles p where p.user_id=auth.uid();result:=result||jsonb_build_object('approvedBy',coalesce(actor,auth.uid()::text));mon:=nullif(btrim(fields->>'period'),'');if mon is null then return result;end if;if mon!~'^\d{4}-(0[1-9]|1[0-2])$' or mon<to_char(lease_row.start_date,'YYYY-MM') or mon>to_char(lease_row.end_date,'YYYY-MM') then raise exception 'DOCUMENT_DISCOUNT_PERIOD_INVALID' using errcode='22023';end if;if lease_row.snapshot->>'rentalTermsVersion'='1' and jsonb_typeof(lease_row.snapshot->'rentEntitlement')='object' then breakdown:=private.aqari_rent_period_breakdown(lease_row.snapshot,mon);discount:=nullif(breakdown->>'discount','')::numeric;else discount:=greatest(coalesce(nullif(lease_row.snapshot->>'contractRent','')::numeric,lease_row.monthly_rent)-coalesce(nullif(lease_row.snapshot->>'rent','')::numeric,lease_row.monthly_rent),0);end if;if coalesce(discount,0)<=0 then raise exception 'DOCUMENT_NO_SAVED_DISCOUNT' using errcode='23514';end if;select x.value into adj from jsonb_array_elements(coalesce(lease_row.snapshot->'rentAdjustments','[]'::jsonb)) x where x.value->>'effectiveMonth'<=mon order by x.value->>'effectiveMonth' desc limit 1;why:=coalesce(nullif(btrim(adj->>'reason'),''),'خصم العقد المحفوظ عند الإبرام');return result||jsonb_build_object('period',mon,'amount',discount::numeric(18,3)::text,'reason',why);end$$;
revoke all on function private.aqari_official_source(uuid,text,text,uuid,uuid,jsonb) from public,anon,authenticated;
